import{_ as t,c as s,o as a,ag as i}from"./chunks/framework.Ci10AEOF.js";const g=JSON.parse('{"title":"Migrating from Mirth Connect on Linux","description":"The eleven-step cutover on Linux, with systemd and file ownership","frontmatter":{"title":"Migrating from Mirth Connect on Linux","description":"The eleven-step cutover on Linux, with systemd and file ownership"},"headers":[],"relativePath":"engine/migrating_linux.md","filePath":"engine/migrating_linux.md","lastUpdated":1793057853000}'),n={name:"engine/migrating_linux.md"};function o(h,e,r,p,d,l){return a(),s("div",null,e[0]||(e[0]=[i(`<h1 id="migrating-from-mirth-connect-on-linux" tabindex="-1">Migrating from Mirth Connect on Linux <a class="header-anchor" href="#migrating-from-mirth-connect-on-linux" aria-label="Permalink to &quot;Migrating from Mirth Connect on Linux&quot;">​</a></h1><p>Read <a href="./migrating_from_mirth_connect.html">Migrating from Mirth Connect</a> first. It covers what changes, what migrates, how extensions are checked, what the keystore holds, and the backups to take before you start.</p><p>Throughout this page Mirth Connect is installed at <code>/opt/mirth</code> and OIE at <code>/opt/oie</code>. Substitute your own locations.</p><p>OIE creates <code>appdata/</code> inside <code>/opt/oie</code> when it first starts. Its location comes from <code>dir.appdata</code>, which ships as a path relative to the installation, so check that property on the Mirth side before copying anything out of <code>/opt/mirth/appdata/</code>.</p><h2 id="what-this-touches" tabindex="-1">What this touches <a class="header-anchor" href="#what-this-touches" aria-label="Permalink to &quot;What this touches&quot;">​</a></h2><p>The tree below lists everything the procedure edits or copies, and the step that does it. See <a href="./installation.html">Installation</a> for the full directory listing.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/opt/oie/</span></span>
<span class="line"><span>├── appdata/                        # replaced wholesale from Mirth (step 8)</span></span>
<span class="line"><span>│   ├── keystore.jks</span></span>
<span class="line"><span>│   ├── server.id</span></span>
<span class="line"><span>│   ├── configuration.properties</span></span>
<span class="line"><span>│   ├── extension.properties</span></span>
<span class="line"><span>│   └── mirthdb/                    # kept on Derby, deleted on an external database (step 8)</span></span>
<span class="line"><span>├── conf/</span></span>
<span class="line"><span>│   ├── mirth.properties            # edit (steps 2, 3, 6 and 9)</span></span>
<span class="line"><span>│   ├── dbdrivers.xml               # copy if you added driver entries (step 6)</span></span>
<span class="line"><span>│   ├── log4j2.properties           # merge custom appenders (step 6)</span></span>
<span class="line"><span>│   ├── mirth-cli-config.properties # copy if you customised it (step 6)</span></span>
<span class="line"><span>│   └── custom.vmoptions            # set JVM settings again, no Mirth equivalent (step 6)</span></span>
<span class="line"><span>├── custom-lib/                     # copy if you use it, not created by the installer (step 6)</span></span>
<span class="line"><span>├── extensions/                     # see Extension compatibility (step 6)</span></span>
<span class="line"><span>└── logs/</span></span>
<span class="line"><span>    └── mirth.log                   # watch (steps 5 and 10)</span></span></code></pre></div><h2 id="_1-install-oie-and-do-not-start-it" tabindex="-1">1. Install OIE, and do not start it <a class="header-anchor" href="#_1-install-oie-and-do-not-start-it" aria-label="Permalink to &quot;1. Install OIE, and do not start it&quot;">​</a></h2><p>Run the installer with the bundled JRE, choosing a directory separate from the Mirth installation. Do not let the installer start the service. If it starts the service anyway, stop the service before going further.</p><p>Nothing in the engine prevents two servers from attaching to one database. Each one deploys whatever it finds.</p><h2 id="_2-change-the-ports" tabindex="-1">2. Change the ports <a class="header-anchor" href="#_2-change-the-ports" aria-label="Permalink to &quot;2. Change the ports&quot;">​</a></h2><p>OIE ships the same <code>http.port = 8080</code> and <code>https.port = 8443</code> as Mirth, and the installer never prompts for them. Edit <code>/opt/oie/conf/mirth.properties</code> and set both to values nothing else on the host is using. <code>http.host</code> and <code>https.host</code> both ship as <code>0.0.0.0</code> if you also want to narrow the interface.</p><p>These are the server&#39;s own administrator and API ports. Channel connector ports are stored in the channels themselves, which live in the database, so this setting does not move them. Step 3 is what keeps those from binding.</p><h2 id="_3-turn-off-startup-deploy" tabindex="-1">3. Turn off startup deploy <a class="header-anchor" href="#_3-turn-off-startup-deploy" aria-label="Permalink to &quot;3. Turn off startup deploy&quot;">​</a></h2><p>In <code>/opt/oie/conf/mirth.properties</code>:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.startupdeploy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = false</span></span></code></pre></div><p>The shipped default is <code>true</code>. With it on, the server deploys every channel in the database at startup, and starting a channel binds its connector ports. If OIE starts against your production database while Mirth is still running, both servers try to bind the same connector ports.</p><h2 id="_4-set-the-service-account-and-file-ownership" tabindex="-1">4. Set the service account and file ownership <a class="header-anchor" href="#_4-set-the-service-account-and-file-ownership" aria-label="Permalink to &quot;4. Set the service account and file ownership&quot;">​</a></h2><p>The install4j configuration sets no service account, so the service runs as root on Linux. See <a href="./security_posture_and_hardening.html">Security Posture and Hardening</a> for why a production host should not leave it that way.</p><p>Check what the installer generated before overriding it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oieservice</span></span></code></pre></div><p>Create the <code>oie</code> account:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> useradd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --system</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --home-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/sbin/nologin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oie</span></span></code></pre></div><p>Then set the account with a drop-in and reload:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oieservice</span></span></code></pre></div><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=oie</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=oie</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oie:oie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie</span></span></code></pre></div><p>The whole install tree needs to be writable by that account. All of these are written while the server runs, relative to <code>/opt/oie</code>:</p><table tabindex="0"><thead><tr><th>Path</th><th>When</th></tr></thead><tbody><tr><td><code>conf/mirth.properties</code></td><td>Saved on every boot</td></tr><tr><td><code>conf/log4j2.properties</code></td><td>Rewritten if a legacy <code>dir.logs</code> property is present</td></tr><tr><td><code>appdata/keystore.jks</code></td><td>Rewritten on every boot</td></tr><tr><td><code>appdata/server.id</code></td><td>Created on first boot</td></tr><tr><td><code>appdata/configuration.properties</code></td><td>Written when the configuration map changes</td></tr><tr><td><code>appdata/extension.properties</code></td><td>Created if absent, and rewritten on every boot</td></tr><tr><td><code>appdata/temp</code></td><td>Created at startup and set as <code>java.io.tmpdir</code></td></tr><tr><td><code>logs/</code></td><td><code>mirth.log</code> and its rotated archives</td></tr><tr><td><code>extensions/</code></td><td>Pending installs and uninstalls are applied at startup</td></tr></tbody></table><h2 id="_5-start-oie-then-stop-it" tabindex="-1">5. Start OIE, then stop it <a class="header-anchor" href="#_5-start-oie-then-stop-it" aria-label="Permalink to &quot;5. Start OIE, then stop it&quot;">​</a></h2><p>Start the service and confirm it comes up. Nothing has moved across from the Mirth engine yet, so OIE runs on the shipped configuration: an empty embedded Derby database it creates inside its own <code>appdata/</code>, on the ports you set in step 2.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oieservice</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/logs/mirth.log</span></span></code></pre></div><p>Log in to the Administrator on the port you set in step 2, as <code>admin</code> with the password the server wrote to <code>/opt/oie/logs/mirth.log</code> (see <a href="./accessing_the_administrator.html#initial-admin-password">Initial admin password</a>). This tests the install, the bundled JRE, the service account and the file ownership while Mirth is still running and its data has not been touched.</p><p>Stop the service before going on.</p><p>Everything this step wrote into <code>/opt/oie/appdata/</code> is scratch, and step 8 deletes the directory outright. That includes the keystore it generated. Creating a keystore also replaces the shipped default <code>keystore.storepass</code> and <code>keystore.keypass</code> in <code>/opt/oie/conf/mirth.properties</code> with fresh random values, which is why the next step has to bring Mirth&#39;s across: they are the passwords to Mirth&#39;s keystore, and that is the keystore you end up with. Because the shipped database is Derby, this start also appends <code>;upgrade=true</code> to <code>database.url</code> in the same file.</p><h2 id="_6-merge-the-configuration-files" tabindex="-1">6. Merge the configuration files <a class="header-anchor" href="#_6-merge-the-configuration-files" aria-label="Permalink to &quot;6. Merge the configuration files&quot;">​</a></h2><p>With OIE stopped and Mirth still running, bring the configuration across. Merge property by property. Do not replace whole files, for the reason given under <a href="./migrating_from_mirth_connect.html#what-migrates">What migrates</a>.</p><p><strong>From <code>/opt/mirth/conf/mirth.properties</code>:</strong></p><ul><li><code>keystore.storepass</code> and <code>keystore.keypass</code>, which must match the keystore step 8 copies over</li><li><strong>On an external database</strong>, the <code>database.*</code> block: <code>database</code>, <code>database.url</code>, <code>database.username</code>, <code>database.password</code>, and the connection pool and retry settings if you tuned them</li><li><strong>On Derby</strong>, leave <code>database</code> and <code>database.url</code> at OIE&#39;s shipped values. They already point at <code>\${dir.appdata}/mirthdb</code>, which is exactly where step 8 puts Mirth&#39;s database</li><li><code>configurationmap.path</code> if you moved it off the default</li><li><code>server.includecustomlib</code> if you set it to <code>true</code>, since OIE ships it as <code>false</code></li><li>Leave <code>http.port</code> and <code>https.port</code> at your step 2 values for now</li><li>Leave <code>server.startupdeploy</code> at <code>false</code></li><li>Leave <code>version</code> alone</li><li>Leave <code>dir.appdata</code> alone. OIE reads its own <code>appdata/</code>, which step 8 fills with a copy of Mirth&#39;s. Pointing it at Mirth&#39;s directory would leave both servers sharing one</li></ul><p><strong>Also from <code>/opt/mirth/conf/</code>:</strong> <code>dbdrivers.xml</code> if you added driver entries, <code>mirth-cli-config.properties</code> if you customised it, and any custom appenders in <code>log4j2.properties</code>. JVM settings such as heap size have no matching path to copy from. OIE splits them into an include chain that Mirth does not have, so set yours again in <code>/opt/oie/conf/custom.vmoptions</code>, which is included last and so wins over the defaults. Do not put them in <code>base_includes.vmoptions</code>, the shipped base options.</p><p><strong>Outside <code>conf/</code>:</strong> <code>/opt/mirth/extensions/</code> and <code>/opt/mirth/custom-lib/</code>. Copy only the extensions you added yourself into <code>/opt/oie/extensions/</code>, not the ones Mirth bundles: copying all of Mirth&#39;s <code>extensions/</code> puts Mirth&#39;s copies of the bundled extensions over OIE&#39;s, and the server fails to start. Check each one against <a href="./migrating_from_mirth_connect.html#extension-compatibility">Extension compatibility</a>. Premium extensions do not come across. Copy <code>custom-lib/</code> if you use it, and check <code>server.includecustomlib</code>, because jars there are not on the classpath when it is <code>false</code>.</p><h2 id="_7-stop-mirth" tabindex="-1">7. Stop Mirth <a class="header-anchor" href="#_7-stop-mirth" aria-label="Permalink to &quot;7. Stop Mirth&quot;">​</a></h2><p>Stop the Mirth service and confirm the process is gone. That covers every port it held, the channel connector ports as well as the administrator ones.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcservice</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is-active</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcservice</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgrep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -af</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/mirth</span></span></code></pre></div><p><code>pgrep</code> matches on the install path because a pattern such as <code>MirthLauncher</code> matches both servers: their launcher classes are <code>MirthLauncher_mcservice</code> for Mirth and <code>MirthLauncher_oieservice</code> for OIE. Nothing should be printed.</p><p>On Derby this is what makes the database safe to copy, because a Derby database has to be cleanly shut down before it can be copied. On an external database it is what keeps two servers off the same data.</p><h2 id="_8-copy-the-application-data" tabindex="-1">8. Copy the application data <a class="header-anchor" href="#_8-copy-the-application-data" aria-label="Permalink to &quot;8. Copy the application data&quot;">​</a></h2><p>Replace OIE&#39;s <code>appdata/</code> with Mirth&#39;s. Delete OIE&#39;s first: step 5 created one, and copying into it would nest Mirth&#39;s directory inside it as <code>appdata/appdata/</code> and leave OIE&#39;s generated files in place.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/appdata</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/mirth/appdata</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/appdata</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oie:oie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/appdata</span></span></code></pre></div><p><code>cp -p</code> preserves Mirth&#39;s ownership, so the chown from step 4 has to run again. Without it OIE cannot rewrite <code>keystore.jks</code> on boot and logs <code>Could not initialize security settings.</code> On Derby it then cannot write the root-owned database either, logs <code>Error establishing connection to database, aborting startup</code>, and exits.</p><p>On Derby you are done: <code>appdata/mirthdb/</code> is your database and it has just come across with everything else. On an external database, delete it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/appdata/mirthdb</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Do not leave a copied mirthdb on an external database</p><p>If the <code>database.*</code> block was never merged in step 6, <code>database.url</code> still points at <code>\${dir.appdata}/mirthdb</code>, so OIE starts on this copy of your Mirth data and looks healthy: channels present, messages there, statistics populated. Your real database sits untouched and nothing processes. With the directory deleted, OIE creates a new, empty database there instead, and the checks in step 10 catch it.</p></div><h2 id="_9-put-the-ports-back" tabindex="-1">9. Put the ports back <a class="header-anchor" href="#_9-put-the-ports-back" aria-label="Permalink to &quot;9. Put the ports back&quot;">​</a></h2><p>Set <code>http.port</code> and <code>https.port</code> in <code>/opt/oie/conf/mirth.properties</code> to the values Mirth was serving on, if you want the Administrator and the API where your users and scripts expect them. Skip this if you have decided to leave OIE on the new ports.</p><h2 id="_10-start-oie-then-deploy" tabindex="-1">10. Start OIE, then deploy <a class="header-anchor" href="#_10-start-oie-then-deploy" aria-label="Permalink to &quot;10. Start OIE, then deploy&quot;">​</a></h2><p>Start the service and watch the log. This is where the server checks the recorded schema version and migrates if it needs to, as described under <a href="./migrating_from_mirth_connect.html#what-migrates">What migrates</a>.</p><p>On Derby, <code>database.url</code> carries the <code>;upgrade=true</code> that step 5 appended. The Derby version shipped here has not changed since long before the fork, so nothing is upgraded.</p><p>Check before deploying anything:</p><ul><li>No <code>Could not initialize security settings.</code> in <code>/opt/oie/logs/mirth.log</code></li><li>You can log in, and your users exist</li><li>Your channels are present, and the extensions you need are loaded</li></ul><p>Then deploy channels a few at a time. Once they are all deployed and processing, set <code>server.startupdeploy</code> back to <code>true</code> if you want channels deployed automatically, and restart the service to confirm that startup path works before you rely on it at the next reboot.</p><h2 id="_11-disable-the-mirth-installation" tabindex="-1">11. Disable the Mirth installation <a class="header-anchor" href="#_11-disable-the-mirth-installation" aria-label="Permalink to &quot;11. Disable the Mirth installation&quot;">​</a></h2><p>Stopping the service in step 7 did not stop it starting again. Disable it, so that a reboot does not bring Mirth up alongside OIE competing for the same database and the same connector ports.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcservice</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is-enabled</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcservice</span></span></code></pre></div><p>Leave the files in place until you are satisfied with the new server. Going back to Mirth needs them as well as the database backup. When you no longer want them, archive them off the host.</p>`,65)]))}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
